    let path = [];

    const dfs = (row, col, steps, currentPath) => {
        if (steps === k) {
            if (currentPath.join('') < minPathValue) {
                minPathValue = currentPath.join('');
                path = currentPath.slice();
            }
            return;
        }

        for (let i = 0; i < 4; i++) {
            const newRow = row + directions[i][0];
            const newCol = col + directions[i][1];

            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N) {
                dfs(newRow, newCol, steps + 1, currentPath.concat(grid[newRow][newCol]));
            }
        }
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, 1, [grid[i][j]]);
        }
    }

    return path;
}

